لمدة يحددها الحكم بحيث لا تزيد عن خمس سنوات.
فإن لم يكن من الممكن الحكم بالتجريد من الحقوق الوطنية، إما لكون المتهم مغربيا
سبق تجريده من هذه الحقوق، وإما لكونه أجنبيا وجب الحكم بالسجن من خمس سنوات إلى$art$, 30, $art$windows-ocr-ar$art$, 0.646, 16, 16, $art$الباب الأول؛ في العقوبات الأصلية$art$),
