ويكون المدير العام للأمن الوطني مختصا بالسهر على احترام الحكم بالمنع من الإقامة
إذا اقتضى الحال، أن يسلم للمعنيين بالأمر رخصا مؤقتة بالإقامة في الأماكن الممنوعة،
