للفصن 77
الإيداع القضائي يستمر طالما استوجب ذلك الأمن العام وعلاج الشخص المأمور
ويبقى الشخص المودع تحت الملاحظة، ويجب فحصه كلما رأى الطبيب المعالج
ضرورة ذلك، وعلى أي حال كل ستة أشهر.
وإذا استقر رأي الطبيب المعالج على إنهاء الإيداع، فإنه يجب أن يخطر بذلك رئيس
النيابة العامة بمحكمة الاستئناف الذي له أن يطعن فى قرار الإخراج في ظرف عشرة أيام
ابتداء من تسلمه ذلك الإخطار، وذلك وفق الشروط المقررة في الفصل 28 من ظهير
2l شوال 1378 الخاص بالوقاية والعلاج من الأمراض العقلية وحماية المرضى المصابين
وهذا الطعن يوقف مفعول الأمر بالإخراج.،
26 - الجريدة الرسمية عدد 2429 بتاريخ 7 ذو القعدة 1378 (15 ماي 1959)، ص 7()15.$art$, 77, $art$windows-ocr-ar$art$, 0.606, 28, 28, $art$الباب الأول: في مختلف التدابير الوقائية الشخصية والعينية$art$),
  ($art$78$art$, $art$الفصل 78$art$, $art$إذا قررت محكمة الموضوع، بعد الخبرة الطبية، أن مرتكب جناية أو جنحة، رغم كونه
قادرا على الدفاع عن نفسه في الدعوى، إلا أنه كان مصابا وقت الأفعال المنسوبة إليه
بضعف في قواه العقلية يترتب عليه نقص مسؤوليته، فإنه يجب عليها:
l - أن تثبت أن الأفعال المتابع من أجلها المتهم منسوبة إليه.
2 - أن تصرح بأن مسؤوليته ناقصة بسبب ضعف في قواه العقلية وقت ارتكاب الفعل.
3 - أن تصدر الحكم بالعقوبة.
4 - أن تأمر، إذا اقتضى الأمر ذلك، بإدخال المحكوم عليه في مؤسسة لعلاج الأمراض
قبل تنفيذ العقوبة السالبة للحرية. ومدة بقائه في هذه المؤسسة تخصم من مدة العقوبة،،
وينتهى إيداعه في المؤسسة وفق الشروط المقررة في الفقرة الأخيرة من الفصل 77.
الفصل و
إذا قررت محكمة الموضوع، بعد الخبرة الطبية، أن الشخص المتابع لديها بجناية أو
جنحة كامل المسؤولية أو ناقص المسؤولية بالنسبة للوقائع المنسوبة إليه، ولكن بسبب خلل
في قواه العقلية طرأ عليه أو اشتد أثره بعد ارتكاب الفعل، أصبح غير قادر على الدفاع عن
نفسه في الدعوى، فإنه يجب عليها:
l - أن تقرر أن المتهم عاجز عن إبداء دفاعه بسبب خلل في قواه العقلية.
2 - أن تأمر بوقف النظر في الدعوى.
3 - أن تأمر بإدخاله في مؤسسة لعلاج الأمراض العقلية.
ويبقى الأمر بالاعتقال ساريا بالنسبة للمتهم حتى يتم إيداعه فعلا.
ويجب على الطبيب المعالج أن يخطر رئيس النيابة العمومية بقرار إخراجه في ظرف
عشرة أيام على الأقل قبل تنفيذ الأمر بالخروج، ويبقى الأمر بالاعتقال الذي كان نافذا وقت
إدخاله بالمؤسسة ساري المفعول وتستأنف المتابعة، بناء على طلب النيابة العمومية وفي
حالة صدور حكم بعقوبة سالبة للحرية، فإن محكمة الموضوع يمكن لها أن تخصم المدة التي
قضاها في المؤسسة من مدة تلك العقوبة.$art$, 78, $art$windows-ocr-ar$art$, 0.645, 29, 29, $art$الباب الأول: في مختلف التدابير الوقائية الشخصية والعينية$art$),
  ($art$80$art$, $art$الفصل 80$art$, $art$الوضع القضائي في مؤسسة للعلاج هو أن يجعل تحت المراقبة بمؤسسة ملائمة -
وبمقتضى حكم صادر عن قضاء الحكم - شخص ارتكب أو ساهم أو شارك في جناية أو
جنحة تأديبية أو ضبطية، وكان مصابا بتسمم مزمن ترتب عن تعاط للكحول أو المخدرات
إذا ظهر أن لإجرامه صلة بذلك التسمم.$art$, 79, $art$windows-ocr-ar$art$, 0.657, 29, 29, $art$الباب الأول: في مختلف التدابير الوقائية الشخصية والعينية$art$),
  ($art$81$art$, $art$الفصل 81$art$, $art$إذا ارتأى قضاء الحكم تطبيق مقتضيات الفصل السابق تعين
l - أن يصرح بأن الفعل المتابع من أجله صادر عن المتهم.
2 - أن يثبت صراحة أن إجرام مرتكب الفعل مرتبط بتسمم مزمن مترتب عن تعاطى
الكحول أو المخدرات.
3 أن يحكم بالعقوبة.
4 - أن يأمر، علاوة على ذلك، بالوضع القضائي داخل مؤسسة للعلاج، لمدة لا تزيد
عن سنتين.
ويطبق على المحكوم عليه تدبير الوضع القضائي قبل تنفيذ العقوبة، ما لم تقرر
المحكمة خلاف ذلك$art$, 80, $art$windows-ocr-ar$art$, 0.613, 30, 30, $art$الباب الأول: في مختلف التدابير الوقائية الشخصية والعينية$art$),
  ($art$82$art$, $art$الفصل 82$art$, $art$يلغى التدبير الصادر بالوضع القضائي في مؤسسة للعلاج عندما يتبين أن الأسباب التي
استوجبته قد انتفت.
إذا قر رأي الطبيب، رئيس مؤسسة للعلاج، على أن يجعل حدا لهذا التدبير فإنه يعلم
بذلك رئيس النيابة العمومية بمحكمة الاستئناف الذي يمكن له، داخل العشرة أيام الموالية
لتوصله بالإعلام المذكور، أن يطعن في قرار الطبيب، وفقا لمقتضيات الفصل 77.$art$, 81, $art$windows-ocr-ar$art$, 0.654, 30, 30, $art$الباب الأول: في مختلف التدابير الوقائية الشخصية والعينية$art$),
  ($art$83$art$, $art$الفصل 83$art$, $art$الوضع القضائي في مؤسسة فلاحية هو إلزام الحكم للمحكوم عليه من أجل جناية أو من
أجل أية جنحة عقابها الحبس قانونا بأن يقيم في مركز مختص يكلف فيه بأشغال فلاحية وذلك
إذا ظهر أن إجرامه مرتبط بتعوده على البطالة أو تبين أنه يتعيش عادة من أعمال غير$art$, 82, $art$windows-ocr-ar$art$, 0.676, 30, 30, $art$الباب الأول: في مختلف التدابير الوقائية الشخصية والعينية$art$),
  ($art$84$art$, $art$الفصل 84$art$, $art$إذا ارتأى قضاء الحكم تطبيق مقتضيات الفصل السابق تعين
l - أن يصرح بأن الفعل المتابع من أجله صادر عن المتهم.
2 - أن يقرر صراحة أن هذا الفعل مرتبط بما اعتاده المحكوم عليه من البطالة أو أن
المحكوم عليه يتعيش عادة من أعمال غير مشروعة.
3 - أن يحكم بالعقوبة.
4 - أن يأمر، علاوة على ذلك، بالوضع القضائي في مؤسسة فلاحية لمدة لا تقل عن
ستة أشهر ولا تتجاوز سنتين.
وتبدأ الإقامة بالمؤسسة الفلاحية بمجرد انتهاء تنفيذ العقوبة.$art$, 83, $art$windows-ocr-ar$art$, 0.641, 30, 31, $art$الباب الأول: في مختلف التدابير الوقائية الشخصية والعينية$art$),
  ($art$85$art$, $art$الفصل 85$art$, $art$يلغى التدبير الصادر بالوضع القضائي المنصوص عليه في الفصل 83 عندما
يئم
سلوك المحكوم عليه عن صلاح حاله.
ويصدر القرار بهذا الإلغاء، بناء على اقتراح من مدير المؤسسة الفلاحية، عن المحكمة
التي كانت أمرت بالوضع القضائي.
عندما يكون التدبير بالوضع القضائى صادرا عن محكمة للجنايات، فإن المحكمة
الجنحية التي ساهمت في تأليف المحكمة الجنائية المذكورة هي التي تكون مختصة بالحكم$art$, 84, $art$windows-ocr-ar$art$, 0.679, 31, 31, $art$الباب الأول: في مختلف التدابير الوقائية الشخصية والعينية$art$),
  ($art$86$art$, $art$الفصل 86$art$, $art$على المحكمة أن تصرح بعدم الأهلية لمزاولة جميع الوظائف والخدمات
العمومية في الأحوال التي نص فيها القانون على ذلك أو إذا تعلق الأمر بجريمة إرهابية؟ 3.
ويجوز الحكم بهذا التدبير في غير الأحوال المشار إليها، عندما تلاحظ المحكمة
وتصرح بمقتضى نص خاص بالحكم أن الجريمة المرتكبة لها علاقة مباشرة بمزاولة
الوظيفة أو الخدمة وأنها تكشف عن وجود فساد في خلق مرتكبها لا يتلاءم ومزاولة الوظيفة
أو الخدمة على الوجه المرضي.
ويحكم بعدم الأهلية لمدة لا يمكن أن تفوق عشر سنوات، ما لم ينص القانون على
خلاف ذلك
وتحسب هذه المدة من اليوم الذي ينتهى فيه تنفيذ العقوبة.$art$, 85, $art$windows-ocr-ar$art$, 0.706, 31, 31, $art$الباب الأول: في مختلف التدابير الوقائية الشخصية والعينية$art$),
  ($art$87$art$, $art$الفصل 87$art$, $art$يتعين الحكم بالمنع من مزاولة مهنة أو نشاط أو فن في حق المحكوم عليهم من أجل
جناية أو جنحة، عندما يتبين للمحكمة أن الجريمة المرتكبة لها علاقة مباشرة بمزاولة المهنة
أو النشاط أو الفن وأنه توجد قرائن قوية يخشى معها أن يصبح المحكوم عليه، إن هو تمادى
على مزاولة ذلك، خطرا على أمن الناس أو صحتهم أو أخلاقهم أو على مدخراتهم.
ويحكم بهذا المنع لمدة لا يمكن أن تفوق عشر سنوات، ما لم ينص القانون على خلاف
وتحسب هذه المدة من اليوم الذي ينتهي فيه تنفيذ العقوبة..
ويسوغ أن يتضمن الحكم بالمؤاخذة الأمر بتنفيذ هذا التدبير مؤقتا، بالرغم من استعمال
أية طريق من طرق الطعن، عادية كانت أو غير عادية.
27 - تم تتميم هذا الفصل بمقتضى المادة الثانية من الباب الأول من القانون رقم 3().3() المتعلق بمكافحة
سالف الذكر.،$art$, 86, $art$windows-ocr-ar$art$, 0.744, 31, 31, $art$الباب الأول: في مختلف التدابير الوقائية الشخصية والعينية$art$),
  ($art$88$art$, $art$الفصل 88$art$, $art$يتعين على المحكمة أن تحكم بسقوط الولاية الشرعية على الأولاد عندما تصدر حكما
من أجل جناية أو جنحة معاقب عليها قانونا بالحبس ارتكبها أحد الأصول على شخص أحد
أطفاله القاصرين، إذا ثبت لديها وصرحت بمقتضى نص خاص بالحكم أن السلوك العادي
للمحكوم عليه يعرض أولاده القاصرين لخطر بدني أو خلقي.
وهذا السقوط يمكن أن يشمل جميع حقوق الولاية أو بعضها، كما يسوغ أن يكون
مقصورا على بعض الأولاد أو على واحد فقط.
ويجوز أن يتضمن الحكم بالمؤاخذة الأمر بتنفيذ هذا التدبير مؤقتا، على الرغم من
استعمال أية طريق من طرق الطعن، عادية كانت أو غير عادية.$art$, 87, $art$windows-ocr-ar$art$, 0.717, 32, 32, $art$الباب الأول: في مختلف التدابير الوقائية الشخصية والعينية$art$),
  ($art$2888-1$art$, $art$الفصل 2888-1$art$, $art$فى حالة الإدانة من أجل جرائم التحرش أو الاعتداء أو الاستغلال الجنسي أو سوء
المعاملة أو العنف ضد المرأة أو القاصرين، أيا كانت طبيعة الفعل أو مرتكبه، يمكن للمحكمة
الحكم بما يلى:
1- منع المحكوم عليه من الاتصال بالضحية أو الاقتراب من مكان تواجدها، أو
التواصل معها بأي وسيلة، لمدة لا تتجاوز خمس سنوات ابتداء من تاريخ انتهاء
العقوبة المحكوم بها عليه أو من تاريخ صدور المقرر القضائي، إذا كانت العقوبة
السالبة للحرية المحكوم بها موقوفة التنفيذ أو غرامة فقط أو عقوبة بديلة.
يضع الصلح المبرم بين الزوجين حدا التنفيذ المنع من الاتصال بالضحية؛
2- خضوع المحكوم عليه، خلال المدة المشار إليها في البند (1) أعلاه أو أثناء تنفيذ
العقوبة السالبة للحرية، لعلاج نفسي ملائم.
يمكن أن يتضمن المقرر القضائي بالمؤاخذة الأمر بتنفيذ هذا التدبير مؤقتا، بالرغم من
استعمال أي طريق من طرق الطعن.
للمحكمة أن تحكم بمنع المحكوم عليه من الاتصال بالضحية أو الاقتراب من
يجوز
مكان تواجدها أو التواصل معها بصفة نهائية، على أن تعلل قرارها بهذا الشأن.$art$, 88, $art$windows-ocr-ar$art$, 0.675, 32, 32, $art$الباب الأول: في مختلف التدابير الوقائية الشخصية والعينية$art$),
  ($art$88-2$art$, $art$الفصل 88-2$art$, $art$يعد الطبيب المعالج تقريرا عن تطور حالة المحكوم عليه بالخضوع للعلاج، كل ثلاثة
أشهر على الأقل ويوجهه إلى قاضي تطبيق العقوبات، للتأكد من تحسن سلوكه وتفادي عودته
إلى نفس الأفعال التي أدين من أجلها.
إذا استقر رأي الطبيب المعالج على إنهاء هذا التدبير قبل الوقت المحدد له فإنه، يخطر
