بهذه الكيفية إلى المملكة.
ويعاقب بنفس العقوبة كل من ساهم في إصدار أو إدخال النقود الملونة المشار إليها.$art$, 386, $art$windows-ocr-ar$art$, 0.758, 113, 113, $art$الفرع 1: في تزييف أو تزوير النقود أو سندات القرض العام$art$),
