تزويرا بإحدى الوسائل الاتية:
1- وضع توقيعات مزورة؛
2- تغيير المحرر أو الكتابة أو التوقيع؛
3- وضع أشخاص وهميين أو استبدال أشخاص بأخرين؛
4- كتابة إضافية أو مقحمة في السجلات أو المحررات العمومية، بعد تمام تحريرها أو$art$, 401, $art$windows-ocr-ar$art$, 0.655, 117, 117, $art$الفرع 3: في تزوير الأوراق الرسمية أو العمومية$art$),
