الفصل 1()4
إذا كان الجرح أو الضرب أو غيرهما من أنواع العنف أو الإيذاء قد نتج عنه عجز
تتجاوز مدته عشرين يوما، فإن العقوبة تكون الحبس من سنة إلى ثلاث سنوات وغرامة من
مائتين" إلى ألف درهم.
وفي حالة توفر سبق الإصرار أو الترصد أو استعمال السلاح، تكون العقوبة الحبس
من سنتين إلى خمس، والغرامة من مائتين وخمسين إلى ألفي درهم.
ويجوز أن يحكم على مرتكب الجريمة، علاوة على ذلك، بالحرمان من واحد أو أكثر
من الحقوق المشار إليها في الفصل ()4 وبالمنع من الإقامة من خمس سنوات إلى عشر.
