الفصل 6()4
من ساهم في مشاجرة أو عصيان أو تجمع بوري وقع أثناءه ضرب أو جرح، يعاقب
بالحبس من ثلاثة أشهر إلى سنتين، ما لم يستحق عقوبة أشد باعتباره مرتكبا لهذا العنف.
أما الرؤساء والمنظمون والمدبرون والمحرضون على المشاجرة أو العصيان أو
التجمع الثوري فإنهم يعاقبون كما لو كانوا هم الذين ارتكبوا أفعال العنف المشار إليها.
انفصل 407 ""
من ساعد، عن علم، شخصا في الأعمال المحضرة أو المسهلة لانتحاره أو زوده
بالسلاح أو السم أو الأدوات اللازمة للانتحار، مع علمه بأنها ستستعمل لهذا الغرض يعاقب،
في حالة وقوع الانتحار، بالحبس من سنة إلى خمس.
