قصد الاستغلال.
يشمل الاستغلال جميع أشكال الاستغلال الجنسي، لا سيما استغلال دعارة الغير
والاستغلال عن طريق المواد الإباحية بما في ذلك وسائل الاتصال والتواصل المعلوماتى،
ويشمل أيضا الاستغلال عن طريق العمل القسري أو السخرة أو التوسل أو الاسترقاق أو
الممارسات الشبيهة بالرق أو نزع الأعضاء أو نزع الأنسجة البشرية أو بيعها، أو الاستغلال
عن طريق إجراء التجارب والأبحاث الطبية على الأحياء، أو استغلال شخص للقيام بأعمال
إجرامية أو في النزاعات المسلحة.
لا يتحقق هذا الاستغلال إلا إذا ترتب عنه سلب إرادة الشخص وحرمانه من حرية
تغيير وضعه وإهدار كرامته الإنسانية، بأي وسيلة كانت ولو تلقى مقابلا أو أجرا عن ذلك.
