- في الحالات المشار إليها في الفقرة الثانية من الفصل السابق، ترفع العقوبة إلى
الضعف
- في الحالة المنصوص عليها في الفقرة الثالثة من نفس الفصل، تكون العقوبة السجن
من عشر إلى عشرين سنة.
