يقصد ببيع الأطفال كل فعل أو تعامل يتم بمقتضاه نقل طفل من شخص أو مجموعة
أشخاص إلى شخص اخر أو مجموعة أشخاص بمقابل كيفما كان نوعه.
يعاقب بالعقوبة المنصوص عليها في الفقرة الأولى من هذا الفصل:
- كل من حرض الأبوين أو أحدهما أو الكافل أو الوصي أو المقدم أو من له سلطة
على طفل أو يتولى رعايته على بيع طفل دون سن الثامنة عشرة أو سهل ذلك أو أعان عليه؛
- كل من قام بالوساطة فى بيع أو شراء طفل دون سن الثامنة عشرة أو سهل ذلك أو
أعان عليه بأية وسيلة من الوسائل.
