الفصول من 494 إلى 231496$art$, 576, $art$windows-ocr-ar$art$, 0.678, 169, 170, $art$الفرع 6: في انتهاك الآداب$art$),
  ($art$497$art$, $art$الفصل 497$art$, $art$يعاقب بالحبس من سنتين إلى عشر سنوات وبغرامة من عشرين ألف إلى مائتي ألف
درهم كل من حرض القاصرين دون الثامنة عشرة على الدعارة أو البغاء أو شجعهم عليها أو
سهلها لهمدة$art$, 577, $art$windows-ocr-ar$art$, 0.767, 170, 170, $art$الفرع 7: في الاستغلال الجنسي وفي إفساد الشباب$art$),
  ($art$498$art$, $art$الفصل 498$art$, $art$يعاقب بالحبس من سنة إلى خمس سنوات وبالغرامة من خمسة آلاف إلى مليون درهم،
ما لم يكن فعله جريمة أشد كل من ارتكب عمدا أحد الأفعال الاتية:
l - أعان أو ساعد أو حمى ممارسة البغاء أو جلب الأشخاص للبغاء وذلك بأية وسيلة
؛
2 - أخذ بأي شكل كان نصيبا مما يحصل عليه الغير عن طريق البغاء أو الدعارة أو
أخذ معونات من شخص اعتاد على تعاطي البغاء أو الدعارة وهو يعلم بذلك؛
3 - عاش مع شخص اعتاد على تعاطي البغاء وهو يعلم بذلك؛
4 - استخدم أو استدرج أو سلم أو حمى شخصا بقصد ممارسة البغاء أو الدعارة
برضاه أو مارس عليه ضغوطا من أجل ممارسة البغاء أو الدعارة أو الاستمرار في ذلك؛
5 - مارس الوساطة، بأية صفة كانت، بين من يتعاطى البغاء أو الدعارة وبين من
يستغل بغاء الغير أو دعارته أو يؤدي مقابلا عن ذلك؛
6 - ساعد من يستغل بغاء أو دعارة الغير على إعطاء تبرير وهمي لموارده المالية؛
