وتطبق نفس العقوبة على سرقة الأخشاب من أماكن قطعها والأحجار من محاجرها
والرمال من الشواطئ أو من الكثبان الرملية الساحلية أو من الأودية أو من أماكنها الطبيعية
والأسماك من بركة أو حوض أو ترعة خاصة.
غير أنه إذا تعلق الأمر بجنحة سرقة الرمال من الأماكن المنصوص عليها في الفقرة
السابقة وتم تحديد الكمية المسروقة منها، فإن الغرامة تكون خمسمائة درهم عن كل متر
مكعب على أن لا تقل عن ألف ومائتي درهم. ويعتبر كل جزء من متر مكعب بمثابة متر
تأمر المحكمة، علاوة على ذلك، بأن يصادر لفائدة الدولة، مع حفظ حقوق الغير حسني
الالات والأدوات والأشياء ووسائل النقل التي استعملت في ارتكاب الجريمة أو كانت،
ستستعمل في ارتكابها أو التي تحصلت منها وكذلك المنح وغيرها من الفوائد التي كوفئ بها
مرتكب الجريمة أو كانت معدة لمكافأته.$art$, 604, $art$windows-ocr-ar$art$, 0.686, 179, 180, $art$الفرع 1: في السرقات وانتزاع الأموال$art$),
