284 - تم تغيير وتتميم الفصل 574-5 أعلاه، بمقتضى المادة الأولى من القانون رقم 12.18، السالف الذكر.
- تم تغيير وتتميم أحكام هذا الفصل بمقتضى المادة الثالثة من القانون ()13.1 المتعلق بتغيير وتتميم مجموعة
القانون الجنائي، سالف الذكر.$art$, 674, $art$windows-ocr-ar$art$, 0.738, 198, 198, $art$الفرع السادس مكرر: غسل الأموال اد$art$),
  ($art$64$art$, $art$المادة 64$art$, $art$كل خرق لحق محمي بموجب هذا القانون يتم اقترافه عن قصد أو نتيجة إهمال بهدف الربح، يعرض
صاحبه للعقوبات المنصوص عليها في القانون الجنائي، وتقوم المحكمة بتحديد مبلغ الغرامة، مع مراعاة الأرباح
التي حصل عليها المدعى عليه من الخرق.
للسلطات القضائية الصلاحية في رفع الحد الأقصى للعقوبات إلى ثلاثة أضعاف عندما تتم إدانة المدعى عليه للمرة
الثانية بسبب اقترافه لعمل يشكل خرقا للحقوق، قبل انقضاء مدة خمس سنوات على إدانته بسبب اقترافه لخرق
كما تطبق السلطات القضائية التدابير والعقوبات المشار إليها في الفصلين 59 و60 من القانون رقم 22.01
المتعلق بالمسطرة الجنائية، سالف الذكر، شريطة ألا يكون قد سبق اتخاذ قرار بشأن هذه العقوبات في محاكمة
التدابير والتعويضات عن الضرر والعقوبات في حالة التجاوز في استعمال الوسائل التقنية وتحريف المعلومات
المتعلقة بنظام الحقوق.$art$, 675, $art$windows-ocr-ar$art$, 0.655, 199, 199, $art$الفرع 7: في بعض الاعتداءات على الملكية الأدبية والفنية قد$art$),
