المؤلف بموجب المواد من 61 إلى 63
أ) صنع أو استيراد، بهدف البيع أو التأجير، لأداة أو وسيلة تم إعدادها أو تكييفها خصيصا لتعطيل أي أداة أو
وسيلة بهدف استعمالها أو منع أو تقليص استنساخ مصنف أو إفساد جودة النسخ أو النسخ المنجزة؛
) صنع أو استيراد، بهدف البيع أو التأجير، لأداة أو وسيلة من شأنها أن تمكن أو تسهل استقبال برنامج مشفر
مذاع أو مبلغ للجمهور بأي شكل آخر من لدن أشخاص غير مؤهلين لاستقباله؛
ج) الحذف أو التغيير بدون تفويض لأي معلومة متعلقة بنظام الحقوق المقدمة على شكل الكتروني؛
د) التوزيع أو الاستيراد بهدف التوزيع، والإذاعة والتبليغ للجمهور أو الوضع في متناول الجمهور بدون تفويض
لمصنفات أداءات ومسجلات صوتية أو بث إذاعي، مع العلم أن المعلومات المتعلقة بنظام الحقوق المقدمة على
شكل الكتروني يكون قد وقع حذفها أو تغييرها بدون ترخيص؛
ه) طبقا لمقتضيات هذه المادة، يقصد بعبارة "المعلومات المتعلقة بنظام الحقوق" تلك التي تمكن من تحديد هوية
المؤلف والمصنف، وفنان الأداء، وأوجه الأداء ومنتج المسجلات الصوتية. والمسجل الصوتي، وهيأة الاذاعة،
والبرنامج الإذاعي، وكل صاحب حق طبقا لهذا القانون، أو أي معلومة متعلقة بشروط وكيفيات استعمال
والإنتاجات الأخرى المقصودة بهذا القانون، وكل رقم أو رمز يمثل هذه المعلومات، عندما يكون أي،
عنصر من عناصر هذه المعلومة ملحقا بنسخة مصنف أو أداءات مثبتة أو نسخة مسجل صوتي، أو برنامج إذاعي
أو يبدو متعلقا بالبث الاذاعي، أو تبليغ مصنفات أو أداءات أو مسجلات صوتية أو برنامج إذاعي للجمهور،
أو وضع رهن تداوله.
عملا بمقتضيات المواد من 6l إلى 63، فإن كل أداة أو وسيلة مشار إليها في الفقرة الأولى، وكل نسخة وقع فيها
