باخرة أو سفينة أو متجر و ورش، إذا كانت هذه المحلات مسكونة أو معدة للسكنى، وعلى
في أي محل آخر مسكون أو معد للسكنى، سواء كان مملوكا له أو لغيره، يعاقب،
ويعاقب بنفس العقوبة من أوقد النار عمدا في ناقلات أو طائرات أو عربات بها
أشخاص أو في عربات ليس بها أحد ولكنها تكون جزءا من قافلة بها أشخاص.$art$, 682, $art$windows-ocr-ar$art$, 0.759, 201, 201, $art$الفرع 8: في التخريب والتعييب والإتلاف$art$),
  ($art$581$art$, $art$الفصل 581$art$, $art$يعاقب بالسجن من عشر إلى عشرين سنة من أوقد النار عمدا في شيء غير مملوك له
الأشياء الاتية:
- مبنى أو بيت أو مسكن أو خيمة أو مأوى، ثابت أو متنقل، أو باخرة أو سفينة أو
ورش و متجر، إذا كان غير مسكون ولا معد للسكنى.
- ناقلة أو طائرة ليس بها أشخاص.
- غابات أو أخشاب مقطوعة أو أخشاب موضوعة في حزم أو أكوام.
- مزروعات قائمة أو تبن أو قش أو محصولات موضوعة في حزم أو أكوام.
- عربات خاوية أو عامرة ببضائع أو منقولات أخرى، إذا لم تكن جزءا من قافلة.$art$, 683, $art$windows-ocr-ar$art$, 0.723, 201, 201, $art$الفرع 8: في التخريب والتعييب والإتلاف$art$),
  ($art$582$art$, $art$الفصل 582$art$, $art$من أوقد النار عمدا أو أمر بذلك في شيء مملوك له من الأشياء المعدودة في الفصل
وسبب بذلك لغيره ضررا أيا كان عن عمد، يعاقب بالسجن من خمس سنوات إلى،
وتطبق نفس العقوبة على من أوقد النار، بناء على أمر المالك، في هذه الحالة.$art$, 684, $art$windows-ocr-ar$art$, 0.751, 201, 201, $art$الفرع 8: في التخريب والتعييب والإتلاف$art$),
  ($art$583$art$, $art$الفصل 583$art$, $art$من أوقد النار عمدا في شيء، أيا كان مملوك له أو لا، موضوع بشكل يسمح بانتقال
فحرق بسبب هذا الاتصال مالا مملوكا للغير من الأموال المعدودة في الفصل 581،،
يعاقب بالسجن من خمس إلى عشر سنوات.$art$, 685, $art$windows-ocr-ar$art$, 0.723, 201, 201, $art$الفرع 8: في التخريب والتعييب والإتلاف$art$),
  ($art$584$art$, $art$الفصل 584$art$, $art$في جميع الحالات المشار إليها في الفصول 581 إلى 583، إذا ترتب عن الحريق
موت شخص أو أكثر، فإن مرتكب الحريق يعاقب بالإعدام.
العمد
وإذا ترتب عن الحريق جروح أو عاهة مستديمة، فالعقوبة هي السجن المؤبد.$art$, 686, $art$windows-ocr-ar$art$, 0.606, 202, 202, $art$الفرع 8: في التخريب والتعييب والإتلاف$art$),
  ($art$585$art$, $art$الفصل 585$art$, $art$تطبق العقوبات المقررة في الفصول ()58 إلى 584، حسب التفصيلات المقررة فيها،
على من خرب عمدا بواسطة مفرقعات أو أية مادة متفجرة، كلا أو جزءا من مبنى أو بيت أو
مسكن أو خيمة أو مأوى أو باخرة أو سفينة أو ناقلة من أي نوع أو عربة أو طائرة أو متجر
أو ورش أو إحدى ملحقاتها، وعلى العموم أي شيء منقول أو عقاري من أي نوع كان؛
ويعاقب على المحاولة كالجريمة التامة.$art$, 687, $art$windows-ocr-ar$art$, 0.789, 202, 202, $art$الفرع 8: في التخريب والتعييب والإتلاف$art$),
  ($art$586$art$, $art$الفصل 586$art$, $art$من خرب عمدا، بواسطة مفرقعات أو أية مادة متفجرة، مسالك عامة أو خاصة أو
حواجز أو سدودا أو طرقا أو قناطر أو منشات الموانئ أو منشات صناعية، يعاقب بالسجن
من عشرين إلى ثلاثين سنة؛ ويعاقب على المحاولة كالجريمة التامة.$art$, 688, $art$windows-ocr-ar$art$, 0.796, 202, 202, $art$الفرع 8: في التخريب والتعييب والإتلاف$art$),
  ($art$587$art$, $art$الفصل 587$art$, $art$من وضع عمدا شحنة متفجرة في طريق عام أو خاص يعاقب بالسجن من عشرين إلى
ثلاثين سنة.$art$, 689, $art$windows-ocr-ar$art$, 0.767, 202, 202, $art$الفرع 8: في التخريب والتعييب والإتلاف$art$),
  ($art$588$art$, $art$الفصل 588$art$, $art$إذا نتج عن الجرائم المشار إليها في أحد الفصلين 586 أو 587 موت شخص أو أكثر،
فإن الجاني يعاقب بالإعدام. وإذا نتج عن الجريمة جروح أو عاهة مستديمة، فالعقوبة هي
السجن المؤبد.$art$, 690, $art$windows-ocr-ar$art$, 0.587, 202, 202, $art$الفرع 8: في التخريب والتعييب والإتلاف$art$),
  ($art$589$art$, $art$الفصل 589$art$, $art$يتمتع بعذر معف من العقاب، بالشروط المقررة في الفصلين 143 و145، أحد الجناة
في الجرائم المشار إليها في الفصول 585 إلى 587، إذا أخطر بها السلطات الإدارية أو
القضائية وكشف عن شخصية الجناة الاخرين وكان ذلك قبل تمام الجريمة وقبل أية متابعة؛
وكذلك إذا مكن من القبض على بقية الجناة ولو كان ذلك بعد ابتداء المتابعة. إلا أنه يجوز أن
يحكم عليه بالمنع من الإقامة من عشر إلى عشرين سنة.$art$, 691, $art$windows-ocr-ar$art$, 0.638, 202, 202, $art$الفرع 8: في التخريب والتعييب والإتلاف$art$),
  ($art$590$art$, $art$الفصل 590$art$, $art$من خرب أو هدم عمدا بأية وسيلة كانت، كلا أو بعضا من مبان أو قناطر، أو حواجز
أو سدود أو طرق أو منشات الموانئ أو منشات صناعية، يعلم أنها مملوكة لغيره وكذلك من
تسبب في انفجار آلة بخارية، أو تخريب محرك آلي في منشات صناعية، يعاقب بالسجن من
خمس سنوات إلى عشر.
وإذا نتج عن الجريمة المشار إليها في الفقرة السابقة قتل إنسان أو جروح أو عاهة
مستديمة للغير، فإن الجاني يعاقب بالإعدام في حالة القتل وبالسجن من عشر إلى عشرين
سنة فى الحالات الأخرى.$art$, 692, $art$windows-ocr-ar$art$, 0.739, 202, 203, $art$الفرع 8: في التخريب والتعييب والإتلاف$art$),
  ($art$591$art$, $art$الفصل 591$art$, $art$من وضع في ممر أو طريق عام شيئا يعوق مرور الناقلات، أو استعمل أي وسيلة
كانت لعرقلة سيرها، وكان غرضه من ذلك التسبب في حادث أو تعطيل المرور أو
فإنه يعاقب بالسجن من خمس سنوات إلى عشر.،
وإذا نتج عن الجريمة المشار إليها في الفقرة السابقة قتل إنسان أو جروح أو عاهة
مستديمة للغير، فإن الجاني يعاقب بالإعدام في حالة القتل، وبالسجن من عشر إلى عشرين
سنة في الحالات الأخرى.$art$, 693, $art$windows-ocr-ar$art$, 0.725, 203, 203, $art$الفرع 8: في التخريب والتعييب والإتلاف$art$),
  ($art$592$art$, $art$الفصل 592$art$, $art$في غير الحالات المشار إليها في الفصل 276 فإن من يحرق أو يتلف عمدا بأي وسيلة
سجلات أو أصول الوثائق المتعلقة بالسلطة العامة أو صورها الرسمية أو سندات أو،
أو سفتجة أو أوراقا تجارية أو بنكية متضمنة أو منشئة لالتزامات أو تصرفات أو،
فإنه يعاقب بالسجن من خمس إلى عشر سنوات، إن كانت الأوراق المتلفة متعلقة،
