لأجل تطبيق الفصلين السابقين 4 "7 تعتبر الطائرة في حالة تحليق من الوقت الذي تنتهي
فيه عملية الركوب وتغلق فيه جميع الأبواب الخارجية إلى الوقت الذي تفتح فيه هذه الأبواب
لأجل نزول الركاب.
وفي حالة نزول اضطراري يعتبر التحليق مستمرا إلى أن تتكفل السلطة المختصة
بالطائرة والأشخاص والأمتعة الموجودة على متنها.
يعاقب بالسجن من خمس إلى عشر سنوات بصرف النظر عن تطبيق مقتضيات
الفصول ()58 و581 و585 من القانون الجنائي كل من ألحق عمدا بطائرة في حالة عمل
أضرارا تجعلها غير قادرة على التحليق أو من شأنها المس بسلامة تحليقها.
تعتبر الطائرة فى حالة عمل من الوقت الذي يشرع فيه المستخدمون بالأرض أو الطاقم
في إعداد هذه الطائرة لتحليق معين إلى أن ينصرم أجل أربع وعشرين ساعة على كل نزول،
وتمتد مدة العمل كيفما كان الحال إلى مجموع المدة التي توجد الطائرة خلالها في حالة تحليق
حسب مدلول الفقرة الثالثة أعلاه.
