الجوية أو ألحق بها أضرارا أو أخل بسيرها إذا كان من شأن أحد هذه الأعمال المس بسلامة
الطائرة وكذا كل من قدم معلومات يعرف أنها خاطئة قصد المس بسلامة هذه الطائرة.
